head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getCurrentGridStyle]<br/>GridView 컴포넌트의 전체 구조 정의를 JSON 형식의 문자열로 반환합니다.",
    "validation" : [
        "현재 GridView 컴포넌트의 상태가 반영된 전체 구조 정의를 JSON 형식의 문자열을 반환합니다.",
        "Column 순서, Column 너비, 숨겨진 Column, 고정 Column 등 데이터를 제외한 GridView 의 전체 구조를 반환합니다.",
        "getCurrentGridStyle() 메소드의 반환값은 setGridStyle() 메소드의 입력으로 사용할 수 있습니다."
    ]
}



// 추출한 구조 스타일 저장소 (getCurrentGridStyle 반환값 → setGridStyle 복원 입력으로 재사용)
scwin.gVar = { "curStyle" : null };



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// [getCurrentGridStyle] : target1 의 현재 전체 구조 정의 문자열을 반환하여 출력 + gVar 저장
//  - 반환 문자열에는 columnOrder / fixedColumn / 각 컬럼 width / hidden 이 포함되고 행 데이터(값)는 제외된다.
//  - 반환값을 scwin.gVar.curStyle 에 저장하여 [setGridStyle(저장값 복원)] 에서 재사용한다.
scwin.btn_getCurrentGridStyle_onclick = function () {
    let b = wf_body_bottom.getObj("scwin");

    let result = target1.getCurrentGridStyle();

    // 반환값 저장 (setGridStyle 입력으로 사용)
    scwin.gVar.curStyle = result;

    b.setReturnValue("target1.getCurrentGridStyle() 반환 (gVar.curStyle 저장) : " + result);
};



// [setGridStyle(저장값 복원)] : 저장한 구조 스타일(gVar.curStyle)을 같은 그리드(target1)에 적용하여 복원
//  - @spec : getCurrentGridStyle() 의 반환값을 setGridStyle() 입력으로 사용할 수 있다(왕복).
//  - setGridStyle 은 대상 그리드를 제거하고 스타일 doc(동일 id=target1)으로 재생성하므로, 같은 그리드 복원 시 id 충돌이 없다.
//    (헤더 드래그로 컬럼 순서/너비를 바꾼 뒤 이 버튼을 누르면 저장 시점 구조로 되돌아온다.)
//  - 저장 전이면 안내 메시지를 출력한다.
scwin.btn_setGridStyle_onclick = function () {
    let b = wf_body_bottom.getObj("scwin");

    if (!scwin.gVar || !scwin.gVar.curStyle) {
        b.setReturnValue("먼저 [getCurrentGridStyle] 버튼을 클릭하여 현재 구조를 추출(gVar 저장)하세요.");
        return;
    }

    target1.setGridStyle(scwin.gVar.curStyle);

    // setGridStyle 은 그리드를 재생성하므로 재획득 후 복원 결과 출력
    let t1 = $p.getComponentById("target1");
    b.setReturnValue("target1.setGridStyle(gVar.curStyle) 적용 완료 : 저장 시점의 구조(컬럼 순서/너비/숨김/고정)로 복원됩니다.");
    b.setReturnValue("[복원 후] target1.getCurrentGridStyle() 반환 : " + t1.getCurrentGridStyle());
};



// [컬럼 순서 변경] : setColumnOrder 로 컬럼 순서를 역순으로 바꾼다(구조 변경 확인용).
//  - 이후 [setGridStyle(저장값 복원)] 을 누르면 저장 시점 순서로 되돌아온다.
scwin.btn_changeOrder_onclick = function () {
    let b = wf_body_bottom.getObj("scwin");
    target1.setColumnOrder([4, 3, 2, 1, 0]);
    b.setReturnValue("setColumnOrder([4,3,2,1,0]) 실행 → 컬럼 순서 변경 : [" + target1.getColumnOrder() + "]");
};



// [컬럼 너비 변경] : setColumnWidth 로 일부 컬럼 너비를 바꾼다(구조 변경 확인용).
//  - 이후 [setGridStyle(저장값 복원)] 을 누르면 저장 시점 너비로 되돌아온다.
scwin.btn_changeWidth_onclick = function () {
    let b = wf_body_bottom.getObj("scwin");
    target1.setColumnWidth(1, 260);   // 이름 컬럼 140 → 260
    target1.setColumnWidth(3, 60);    // 직급 컬럼 110 → 60
    b.setReturnValue("setColumnWidth(1,260) / setColumnWidth(3,60) 실행 → 이름/직급 컬럼 너비 변경");
};
